sys_script.script:
(function executeRule(current, previous /*null when async*/) {

	var util=new EquipmentRequestUtil();
	var state = current.getValue('state');
	var reserved = current.stock_reserved.toString() === 'true';
    var equipmentId = current.getValue('equipment');
    var qty = current.getValue('quantity');

    // A) Request became Approved -> reserve stock
    if (state === util.STATE.APPROVED && !reserved) {
        if (!util.reserveStock(equipmentId, qty)) {
            gs.addErrorMessage(gs.getMessage('Not enough stock to approve this request.'));
            current.setAbortAction(true);   // nothing is saved, no partial state
            return;
        }
        current.setValue('stock_reserved', true);
        return;
    }

    // B) Rejected / cancelled after stock was reserved -> release (compensating action)
    var releasing = (state === util.STATE.CANCELLED || state === util.STATE.REJECTED);
    if (releasing && reserved) {
        util.releaseStock(equipmentId, qty);
        current.setValue('stock_reserved', false);
    }

})(current, previous);
